begin;
alter table usuarios add column puede_validar_laboratorio boolean not null default false;
alter table cita_solicitudes_cambio add column origen text not null default 'paciente' check(origen in('paciente','medico')),add column solicitante_id bigint references usuarios(id);
create function public.clinica_proteger_permiso_laboratorio() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if new.puede_validar_laboratorio is distinct from old.puede_validar_laboratorio and current_user not in('postgres','service_role','supabase_admin') and clinica_rol() is distinct from 'admin' then raise exception 'Solo administración autoriza la validación de laboratorio' using errcode='42501'; end if;
 return new;
end $$;
create trigger proteger_permiso_laboratorio before update on usuarios for each row execute function clinica_proteger_permiso_laboratorio();

alter table expedientes add column autor_medico_id bigint references perfiles_medicos(id), add column estado_nota text not null default 'borrador' check(estado_nota in('borrador','cerrada')),
 add column cerrada_en timestamptz, add column cerrada_por bigint references usuarios(id), add column contenido jsonb not null default '{}'::jsonb, add column revision bigint not null default 1;
update expedientes e set autor_medico_id=c.medico_id,estado_nota=case when c.estado='atendida' then 'cerrada' else 'borrador' end from citas c where c.id=e.cita_id;
create table consulta_correcciones(id bigint generated by default as identity primary key,expediente_id bigint not null references expedientes(id),autor bigint not null references usuarios(id),motivo text not null,texto text not null,creado_en timestamptz not null default clock_timestamp(),clave uuid not null unique);
create table medico_operaciones(autor bigint not null references usuarios(id),clave uuid not null,solicitud jsonb not null,resultado jsonb not null,creado_en timestamptz not null default clock_timestamp(),primary key(autor,clave));
create table medico_resultados_revisados(solicitud_id bigint not null references solicitudes_analisis(id),medico_id bigint not null references perfiles_medicos(id),version text not null,comentario text,creado_en timestamptz not null default clock_timestamp(),primary key(solicitud_id,medico_id,version));
alter table consulta_correcciones enable row level security;
alter table medico_operaciones enable row level security;
alter table medico_resultados_revisados enable row level security;
create policy correcciones_lectura on consulta_correcciones for select to authenticated using(clinica_sesion_activa() and clinica_expediente(expediente_id) and clinica_rol() in('admin','medico','paciente'));
create policy revisiones_lectura on medico_resultados_revisados for select to authenticated using(clinica_sesion_activa() and (clinica_rol()='admin' or medico_id=clinica_medico()));
grant select on consulta_correcciones,medico_resultados_revisados to authenticated;
revoke insert,update,delete on expedientes from authenticated;
create policy paciente_nota_cerrada on expedientes as restrictive for select to authenticated using(clinica_rol() is distinct from 'paciente' or estado_nota='cerrada');
create policy borrador_del_autor on expedientes as restrictive for select to authenticated using(clinica_rol() is distinct from 'medico' or estado_nota='cerrada' or autor_medico_id=clinica_medico());
create function public.clinica_nota_inmutable() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if old.estado_nota='cerrada' then raise exception 'La nota está cerrada. Añade una corrección sin modificar el original' using errcode='42501'; end if;
 if tg_op='UPDATE' then new.revision:=old.revision+1; return new; end if;
 return old;
end $$;
create trigger consulta_nota_inmutable before update or delete on expedientes for each row execute function clinica_nota_inmutable();

-- Un episodio puede corresponder a una internación o a una cita ambulatoria.
alter table episodios_medicos alter column internacion_id drop not null;
alter table episodios_medicos add column cita_id bigint references citas(id),add constraint episodio_origen_unico check(num_nonnulls(internacion_id,cita_id)=1);
create unique index episodio_consulta_unico on episodios_medicos(cita_id) where cita_id is not null;
create or replace function public.clinica_orden(p_id bigint) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from ordenes_medicas o join episodios_medicos ep on ep.id=o.episodio_id left join internaciones i on i.id=ep.internacion_id left join citas c on c.id=ep.cita_id where o.id=p_id and clinica_paciente(coalesce(i.paciente_id,c.paciente_id)))
$$;
drop policy ordenes_lectura on ordenes_medicas;
create policy ordenes_lectura on ordenes_medicas for select to authenticated using(clinica_rol() in('admin','medico','enfermero','paciente') and clinica_orden(id));
create policy consulta_episodios_lectura on episodios_medicos for select to authenticated using(clinica_rol() in('admin','medico','paciente') and exists(select 1 from citas c where c.id=cita_id and clinica_paciente(c.paciente_id)));
create function public.clinica_control_orden() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare autor bigint;
begin
 if clinica_rol()='medico' then
  select medico_id into autor from episodios_medicos where id=case when tg_op='INSERT' then new.episodio_id else old.episodio_id end;
  if autor is distinct from clinica_medico() then raise exception 'Solo el prescriptor puede modificar esta indicación' using errcode='42501'; end if;
  if tg_op='UPDATE' and (new.episodio_id is distinct from old.episodio_id or new.tipo_orden is distinct from old.tipo_orden) then raise exception 'No se puede cambiar el origen ni el tipo de una orden' using errcode='42501'; end if;
 end if;
 return new;
end $$;
create trigger consulta_control_orden before insert or update on ordenes_medicas for each row execute function clinica_control_orden();
create function public.clinica_autor_episodio() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if clinica_rol()='medico' and new.medico_id is distinct from clinica_medico() then raise exception 'El episodio debe identificar al médico que registra la atención' using errcode='42501'; end if;
 return new;
end $$;
create trigger consulta_autor_episodio before insert on episodios_medicos for each row execute function clinica_autor_episodio();
create function public.clinica_validar_resultado_autorizado() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare cambia boolean;
begin
 if tg_op='INSERT' then cambia:=new.observaciones is not null or new.resultado is not null or new.archivo_resultado is not null or new.fecha_resultado is not null or new.estado_analisis='completado';
 else
  if (new.orden_medica_id,new.analisis_id) is distinct from (old.orden_medica_id,old.analisis_id) then raise exception 'Conserva la identidad del estudio; registra otra solicitud para un estudio diferente' using errcode='42501'; end if;
  cambia:=new.observaciones is distinct from old.observaciones or old.estado_analisis='completado' and new.estado_analisis is distinct from old.estado_analisis or new.resultado is distinct from old.resultado or new.archivo_resultado is distinct from old.archivo_resultado or new.fecha_resultado is distinct from old.fecha_resultado or new.estado_analisis='completado' and old.estado_analisis<>'completado'; end if;
 if cambia and clinica_rol() is not null and clinica_rol()<>'admin' and not exists(select 1 from usuarios where auth_user_id=auth.uid() and esta_activo and rol='medico' and puede_validar_laboratorio) then raise exception 'No tienes autorización para validar resultados de laboratorio' using errcode='42501'; end if;
 return new;
end $$;
create trigger laboratorio_personal_autorizado before insert or update on solicitudes_analisis for each row execute function clinica_validar_resultado_autorizado();

create function public.clinica_consulta_version(p_cita bigint) returns text language sql stable security definer set search_path=public,pg_temp as $$
 select md5(concat_ws(':',c.id,c.estado,c.inicio,c.actualizado_en,coalesce(e.revision,0))) from citas c left join expedientes e on e.cita_id=c.id where c.id=p_cita
$$;
revoke all on function clinica_consulta_version(bigint) from public,anon,authenticated;
create function public.clinica_resultado_version(p_id bigint) returns text language sql stable security definer set search_path=public,pg_temp as $$
 select md5(concat_ws(':',id,resultado,archivo_resultado,fecha_resultado,observaciones,estado_analisis)) from solicitudes_analisis where id=p_id
$$;
revoke all on function clinica_resultado_version(bigint) from public,anon,authenticated;
create function public.clinica_signos_recientes(p_paciente bigint) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('valores',r.datos->'valores','fecha',r.observado_en,'autor',u.nombre_completo) from enfermeria_registros r join usuarios u on u.id=r.autor where r.paciente_id=p_paciente and r.tipo='signos' and not exists(select 1 from enfermeria_registros correccion where correccion.corrige_id=r.id) order by r.observado_en desc,r.id desc limit 1
$$;
revoke all on function clinica_signos_recientes(bigint) from public,anon,authenticated,service_role;

create function public.clinica_consulta_leer(p_cita bigint) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare c citas; e expedientes; m perfiles_medicos; paciente perfiles_pacientes; u usuarios;
begin
 perform clinica_requerir_sesion(); select * into c from citas where id=p_cita;
 if c.id is null or clinica_rol() not in('admin','medico') or clinica_rol() is null or not clinica_paciente(c.paciente_id) then raise exception 'Consulta no encontrada o sin acceso' using errcode='42501'; end if;
 select * into e from expedientes where cita_id=c.id; select * into m from perfiles_medicos where id=c.medico_id;
 if clinica_rol()='medico' and (c.medico_id<>clinica_medico() or e.autor_medico_id is distinct from clinica_medico() and e.id is not null) and (e.id is null or e.estado_nota<>'cerrada') then raise exception 'El borrador pertenece a otro médico' using errcode='42501'; end if;
 select * into paciente from perfiles_pacientes where id=c.paciente_id; select * into u from usuarios where id=paciente.usuario_id;
 return jsonb_build_object('cita',jsonb_build_object('id',c.id,'pacienteId',c.paciente_id,'paciente',u.nombre_completo,'nacimiento',paciente.fecha_nacimiento,'medico',(select nombre_completo from usuarios where id=m.usuario_id),'cedula',m.cedula_profesional,'inicio',c.inicio,'estado',c.estado,'motivo',c.motivo,'alertas',paciente.notas_medicas),
 'version',clinica_consulta_version(c.id),'signos',case when e.estado_nota='cerrada' then e.contenido->'signos' else clinica_signos_recientes(c.paciente_id) end,'puedeSolicitarCambio',clinica_rol()='medico' and c.medico_id=clinica_medico(),'puedeEditar',clinica_rol()='admin' or c.medico_id=clinica_medico(),'nota',case when e.id is null then null else to_jsonb(e) end,
 'correcciones',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'texto',r.texto,'motivo',r.motivo,'fecha',r.creado_en,'autor',uu.nombre_completo) order by r.id) from consulta_correcciones r join usuarios uu on uu.id=r.autor where r.expediente_id=e.id),'[]'::jsonb),
 'ordenes',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'tipo',o.tipo_orden,'descripcion',o.descripcion,'instrucciones',o.instrucciones,'estado',o.estado) order by o.id desc) from ordenes_medicas o join episodios_medicos ep on ep.id=o.episodio_id where ep.cita_id=c.id),'[]'::jsonb),
 'catalogo',coalesce((select jsonb_agg(jsonb_build_object('id',id,'nombre',nombre) order by nombre) from catalogo_analisis),'[]'::jsonb));
end $$;

create function public.clinica_medico_panel(p_dia date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare med bigint:=clinica_medico(); dia date:=coalesce(p_dia,(clock_timestamp() at time zone 'America/Mexico_City')::date);
begin
 perform clinica_requerir_sesion(); if clinica_rol() is distinct from 'medico' or med is null then raise exception 'Esta agenda pertenece al médico' using errcode='42501'; end if;
 return jsonb_build_object('dia',dia,'ahora',clock_timestamp(),'puedeValidarLaboratorio',exists(select 1 from usuarios where auth_user_id=auth.uid() and puede_validar_laboratorio),
 'citas',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'pacienteId',c.paciente_id,'paciente',u.nombre_completo,'inicio',c.inicio,'fin',c.fin,'motivo',c.motivo,'estado',c.estado,'llegada',l.llegada,'enConsulta',l.en_consulta,'notaEstado',e.estado_nota) order by c.inicio) from citas c join perfiles_pacientes p on p.id=c.paciente_id join usuarios u on u.id=p.usuario_id left join expedientes e on e.cita_id=c.id left join recepcion_llegadas l on l.cita_id=c.id and l.inicio_cita=c.inicio where c.medico_id=med and clinica_paciente(c.paciente_id) and (c.inicio at time zone 'America/Mexico_City')::date=dia),'[]'::jsonb),
 'abiertas',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'paciente',u.nombre_completo,'inicio',c.inicio)) from citas c join perfiles_pacientes p on p.id=c.paciente_id join usuarios u on u.id=p.usuario_id join recepcion_llegadas l on l.cita_id=c.id and l.inicio_cita=c.inicio where c.medico_id=med and clinica_paciente(c.paciente_id) and c.estado in('pendiente','confirmada') and l.en_consulta is not null),'[]'::jsonb),
 'resultados',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'paciente',u.nombre_completo,'estudio',ca.nombre,'resultado',s.resultado,'fecha',s.fecha_resultado,'conPdf',nullif(s.archivo_resultado,'') is not null,'version',clinica_resultado_version(s.id))) from solicitudes_analisis s join catalogo_analisis ca on ca.id=s.analisis_id join ordenes_medicas o on o.id=s.orden_medica_id join episodios_medicos ep on ep.id=o.episodio_id left join internaciones i on i.id=ep.internacion_id left join citas c on c.id=ep.cita_id join perfiles_pacientes p on p.id=coalesce(i.paciente_id,c.paciente_id) join usuarios u on u.id=p.usuario_id where clinica_paciente(p.id) and s.estado_analisis='completado' and not exists(select 1 from medico_resultados_revisados r where r.solicitud_id=s.id and r.medico_id=med and r.version=clinica_resultado_version(s.id))),'[]'::jsonb),
 'incidencias',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'paciente',u.nombre_completo,'texto',r.datos->>'texto','fecha',r.creado_en)) from enfermeria_registros r join perfiles_pacientes p on p.id=r.paciente_id join usuarios u on u.id=p.usuario_id where r.tipo='incidencia' and clinica_paciente(p.id) and not exists(select 1 from enfermeria_acuses a where a.registro_id=r.id)),'[]'::jsonb));
end $$;

create function public.clinica_medico_operar(p_accion text,p_datos jsonb,p_clave uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare u usuarios; c citas; e expedientes; anterior medico_operaciones; solicitud jsonb; salida jsonb; d jsonb; r jsonb; receta text; ep bigint; orden bigint; analisis bigint; v text;
begin
 perform clinica_requerir_sesion(); select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if u.id is null or u.rol not in('admin','medico') then raise exception 'Sin permiso para registrar atención médica' using errcode='42501'; end if;
 if p_accion is null or p_accion not in('guardar','corregir','orden','revisar','solicitar_cambio') or p_clave is null or jsonb_typeof(p_datos) is distinct from 'object' or length(p_datos::text)>50000 then raise exception 'Solicitud médica inválida'; end if;
 perform pg_advisory_xact_lock(37205,0);
 solicitud:=jsonb_build_object('accion',p_accion,'datos',p_datos);
 select * into anterior from medico_operaciones where autor=u.id and clave=p_clave;
 if found then if anterior.solicitud is distinct from solicitud then raise exception 'El identificador ya fue utilizado para otra solicitud' using errcode='40001'; end if; return anterior.resultado; end if;
 if p_accion='revisar' then
  if u.rol<>'medico' then raise exception 'La revisión clínica corresponde al médico' using errcode='42501'; end if;
  analisis:=(p_datos->>'resultadoId')::bigint;
  if not exists(select 1 from solicitudes_analisis s where s.id=analisis and s.estado_analisis='completado' and clinica_orden(s.orden_medica_id)) then raise exception 'Resultado no encontrado o sin acceso' using errcode='42501'; end if;
  v:=clinica_resultado_version(analisis); if v is distinct from p_datos->>'version' then raise exception 'El resultado cambió. Revísalo nuevamente' using errcode='40001'; end if;
  if length(coalesce(p_datos->>'comentario',''))>2000 then raise exception 'El comentario supera 2000 caracteres'; end if;
  insert into medico_resultados_revisados(solicitud_id,medico_id,version,comentario) values(analisis,clinica_medico(),v,nullif(trim(p_datos->>'comentario'),'')) on conflict do nothing;
  salida:=jsonb_build_object('ok',true,'mensaje','Resultado marcado como revisado.');
 else
  select * into c from citas where id=(p_datos->>'citaId')::bigint for update;
  if c.id is null or not clinica_paciente(c.paciente_id) then raise exception 'Consulta no encontrada o sin acceso' using errcode='42501'; end if;
  if u.rol='medico' and c.medico_id is distinct from clinica_medico() then raise exception 'Solo el médico de la cita puede registrar o corregir su atención' using errcode='42501'; end if;
  select * into e from expedientes where cita_id=c.id;
  if u.rol='medico' and e.id is not null and e.autor_medico_id is distinct from clinica_medico() and p_accion in('guardar','corregir') then raise exception 'La nota pertenece a otro médico' using errcode='42501'; end if;
  if p_datos->>'version' is distinct from clinica_consulta_version(c.id) then raise exception 'La consulta cambió. Actualiza antes de guardar; conserva tu borrador' using errcode='40001'; end if;
  if p_accion='guardar' then
   if e.estado_nota='cerrada' or c.estado not in('pendiente','confirmada') then raise exception 'La consulta no admite cambios. Añade una corrección a la nota cerrada'; end if;
   d:=p_datos->'contenido';
   if jsonb_typeof(d) is distinct from 'object' then raise exception 'Completa el contenido de la consulta'; end if;
   d:=d||jsonb_build_object('signos',clinica_signos_recientes(c.paciente_id));
   if length(coalesce(d->>'diagnostico',''))>8000 or length(coalesce(d->>'plan',''))>8000 or length(coalesce(d->>'subjetivo',''))>8000 or length(coalesce(d->>'objetivo',''))>8000 or jsonb_typeof(coalesce(d->'medicamentos','[]'))<>'array' or jsonb_array_length(coalesce(d->'medicamentos','[]'))>30 then raise exception 'Revisa la extensión y los medicamentos de la consulta'; end if;
   receta:=coalesce(d->>'recetaLibre','');
   for r in select value from jsonb_array_elements(coalesce(d->'medicamentos','[]')) loop
    if jsonb_typeof(r)<>'object' or length(trim(coalesce(r->>'nombre',''))) not between 1 and 200 or length(trim(coalesce(r->>'dosis',''))) not between 1 and 200 or length(trim(coalesce(r->>'via',''))) not between 1 and 120 or length(trim(coalesce(r->>'frecuencia',''))) not between 1 and 200 or length(trim(coalesce(r->>'duracion',''))) not between 1 and 200 then raise exception 'Completa nombre, dosis, vía, frecuencia y duración de cada medicamento'; end if;
    receta:=concat_ws(E'\n',nullif(receta,''),concat(r->>'nombre',' · ',r->>'dosis',' · ',r->>'via',' · ',r->>'frecuencia',' · ',r->>'duracion'));
   end loop;
   if coalesce((p_datos->>'cerrar')::boolean,false) then
    if length(trim(coalesce(d->>'diagnostico','')))=0 or length(trim(coalesce(d->>'plan','')))=0 or length(trim(coalesce(d->>'subjetivo','')))=0 or length(trim(coalesce(d->>'objetivo','')))=0 then raise exception 'Completa motivo/evolución, exploración, diagnóstico y plan antes de finalizar'; end if;
    if not exists(select 1 from recepcion_llegadas l where l.cita_id=c.id and l.inicio_cita=c.inicio and l.en_consulta is not null) then raise exception 'El médico debe iniciar la atención antes de finalizar'; end if;
   end if;
   insert into expedientes(cita_id,autor_medico_id,diagnostico,receta,notas_doctor,contenido,estado_nota,cerrada_en,cerrada_por)
   values(c.id,c.medico_id,nullif(d->>'diagnostico',''),nullif(receta,''),concat_ws(E'\n\n',nullif(d->>'subjetivo',''),nullif(d->>'objetivo',''),nullif(d->>'plan',''),nullif(d->>'pronostico',''),nullif(d->>'seguimiento','')),d,case when coalesce((p_datos->>'cerrar')::boolean,false) then 'cerrada' else 'borrador' end,case when (p_datos->>'cerrar')::boolean then clock_timestamp() end,case when (p_datos->>'cerrar')::boolean then u.id end)
   on conflict(cita_id) do update set diagnostico=excluded.diagnostico,receta=excluded.receta,notas_doctor=excluded.notas_doctor,contenido=excluded.contenido,estado_nota=excluded.estado_nota,cerrada_en=excluded.cerrada_en,cerrada_por=excluded.cerrada_por returning * into e;
   if e.estado_nota='cerrada' then update citas set estado='atendida',actualizado_en=clock_timestamp() where id=c.id; end if;
   salida:=jsonb_build_object('ok',true,'id',e.id,'mensaje',case when e.estado_nota='cerrada' then 'Consulta finalizada y nota cerrada.' else 'Borrador guardado.' end);
  elsif p_accion='corregir' then
   if e.id is null or e.estado_nota<>'cerrada' then raise exception 'Las correcciones se añaden a una nota cerrada'; end if;
   if length(trim(coalesce(p_datos->>'motivo',''))) not between 1 and 1000 or length(trim(coalesce(p_datos->>'texto',''))) not between 1 and 8000 then raise exception 'Indica el motivo y el texto de la corrección'; end if;
   insert into consulta_correcciones(expediente_id,autor,motivo,texto,clave) values(e.id,u.id,trim(p_datos->>'motivo'),trim(p_datos->>'texto'),p_clave);
   salida:=jsonb_build_object('ok',true,'id',e.id,'mensaje','Corrección añadida. La nota original se conserva.');
  elsif p_accion='solicitar_cambio' then
   if u.rol<>'medico' or c.estado not in('pendiente','confirmada') or c.inicio<=clock_timestamp()+interval '2 hours' or exists(select 1 from recepcion_llegadas where cita_id=c.id and inicio_cita=c.inicio) then raise exception 'Solo puedes solicitar otro horario con más de dos horas de anticipación y antes de la llegada'; end if;
   if length(trim(coalesce(p_datos->>'motivo',''))) not between 10 and 800 then raise exception 'Describe el motivo del cambio (10 a 800 caracteres)'; end if;
   if exists(select 1 from cita_solicitudes_cambio where cita_id=c.id and estado='pendiente') then raise exception 'Ya existe una solicitud pendiente para esta cita. Recepción debe revisarla'; end if;
   insert into cita_solicitudes_cambio(cita_id,usuario_id,disponibilidad,canal,origen,solicitante_id) values(c.id,(select usuario_id from perfiles_pacientes where id=c.paciente_id),'Solicitud del médico '||u.nombre_completo||': '||trim(p_datos->>'motivo'),'aplicacion','medico',u.id) returning id into orden;
   insert into notificaciones(usuario_id,tipo,titulo,mensaje,cita_id,clave) select id,'solicitud_cambio','El médico solicita coordinar otro horario','Hay una solicitud de cambio para la cita #'||c.id||'. Recepción contactará al paciente; la reserva actual se conserva.',c.id,'solicitud-medico:'||orden from usuarios where esta_activo and (rol in('admin','recepcionista') or id=(select usuario_id from perfiles_pacientes where id=c.paciente_id));
   salida:=jsonb_build_object('ok',true,'id',orden,'mensaje','Solicitud enviada a recepción. La cita actual se conserva.');
  elsif p_accion='orden' then
   if c.estado in('cancelada_paciente','cancelada_medico','no_asistio') then raise exception 'No se pueden emitir órdenes desde una cita cancelada o no asistida'; end if;
   if p_datos->>'tipo' not in('analisis','medicamento','tratamiento','procedimiento') or length(trim(coalesce(p_datos->>'descripcion',''))) not between 1 and 2000 or length(trim(coalesce(p_datos->>'instrucciones',''))) not between 1 and 8000 then raise exception 'Completa el tipo, la descripción y las indicaciones de la orden'; end if;
   if p_datos->>'tipo'='analisis' and not exists(select 1 from catalogo_analisis where id=(p_datos->>'analisisId')::bigint) then raise exception 'Selecciona un estudio del catálogo'; end if;
   insert into episodios_medicos(cita_id,medico_id,tipo_episodio,descripcion) values(c.id,c.medico_id,'Consulta ambulatoria','Indicaciones vinculadas a la cita') on conflict(cita_id) where cita_id is not null do update set cita_id=excluded.cita_id returning id into ep;
   insert into ordenes_medicas(episodio_id,tipo_orden,descripcion,instrucciones) values(ep,(p_datos->>'tipo')::tipo_orden_medica,trim(p_datos->>'descripcion'),trim(p_datos->>'instrucciones')) returning id into orden;
   if p_datos->>'tipo'='analisis' then insert into solicitudes_analisis(orden_medica_id,analisis_id) values(orden,(p_datos->>'analisisId')::bigint); end if;
   salida:=jsonb_build_object('ok',true,'id',orden,'mensaje','Orden ambulatoria registrada.');
  end if;
 end if;
 insert into medico_operaciones(autor,clave,solicitud,resultado) values(u.id,p_clave,solicitud,salida);
 return salida;
end $$;
-- Tampoco se puede finalizar una consulta mediante una actualización REST aislada.
create function public.clinica_cierre_con_nota() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if old.estado='atendida' and new is distinct from old then raise exception 'La cita ya fue finalizada y no puede reabrirse. Añade una aclaración a su nota' using errcode='42501'; end if;
 if (new.medico_id,new.paciente_id) is distinct from (old.medico_id,old.paciente_id) and exists(select 1 from expedientes where cita_id=old.id) then raise exception 'La cita ya tiene una nota clínica. Conserva su paciente y médico; agenda otra cita para una atención diferente' using errcode='42501'; end if;
 if clinica_rol()='medico' and (new.inicio,new.fin,new.medico_id,new.paciente_id) is distinct from (old.inicio,old.fin,old.medico_id,old.paciente_id) then raise exception 'Solicita el cambio de horario a recepción para coordinarlo con el paciente' using errcode='42501'; end if;
 if new.estado='atendida' and old.estado<>'atendida' and not exists(select 1 from expedientes where cita_id=new.id and estado_nota='cerrada') then raise exception 'Finaliza la consulta guardando su nota completa en una sola operación'; end if;
 return new;
end $$;
create trigger consulta_cierre_con_nota before update on citas for each row execute function clinica_cierre_con_nota();
-- Conserva el portal y las notificaciones existentes, ampliando su origen a citas.
do $adaptar$
declare original text; nueva text;
begin
 select pg_get_functiondef('public.clinica_portal_paciente_v23()'::regprocedure) into original;
 nueva:=replace(original,'join episodios_medicos e on e.id=o.episodio_id join internaciones i on i.id=e.internacion_id','join episodios_medicos e on e.id=o.episodio_id left join internaciones i on i.id=e.internacion_id left join citas amb on amb.id=e.cita_id');
 nueva:=replace(nueva,'where i.paciente_id=p.id','where coalesce(i.paciente_id,amb.paciente_id)=p.id');
 nueva:=replace(nueva,'where c.paciente_id=p.id order by e.creado_en','where c.paciente_id=p.id and e.estado_nota=''cerrada'' order by e.creado_en');
 if nueva=original then raise exception 'Revisa el origen de los resultados del portal'; end if;
 execute nueva;
 select pg_get_functiondef('public.clinica_historial_paciente(bigint)'::regprocedure) into original;
 nueva:=replace(original,'where c.paciente_id=p_paciente order','where c.paciente_id=p_paciente and (clinica_rol()<>''paciente'' or e.estado_nota=''cerrada'') and (clinica_rol()<>''medico'' or e.estado_nota=''cerrada'' or c.medico_id=clinica_medico()) order');
 if nueva=original then raise exception 'Revisa la lectura del historial del paciente'; end if;
 execute nueva;
 select pg_get_functiondef('public.clinica_avisar_atencion()'::regprocedure) into original;
 nueva:=replace(original,'select i.paciente_id,i.medico_responsable_id into v_paciente,v_medico','select coalesce(i.paciente_id,amb.paciente_id),coalesce(e.medico_id,i.medico_responsable_id,amb.medico_id) into v_paciente,v_medico');
 nueva:=replace(nueva,'join internaciones i on i.id=e.internacion_id','left join internaciones i on i.id=e.internacion_id left join citas amb on amb.id=e.cita_id');
 if nueva=original then raise exception 'Revisa las notificaciones de las órdenes ambulatorias'; end if;
 execute nueva;
end $adaptar$;
revoke all on function clinica_nota_inmutable(),clinica_proteger_permiso_laboratorio(),clinica_control_orden(),clinica_autor_episodio(),clinica_validar_resultado_autorizado(),clinica_cierre_con_nota() from public,anon,authenticated,service_role;
revoke all on function clinica_consulta_leer(bigint),clinica_medico_panel(date),clinica_medico_operar(text,jsonb,uuid) from public,anon;
grant execute on function clinica_consulta_leer(bigint),clinica_medico_panel(date),clinica_medico_operar(text,jsonb,uuid) to authenticated;
create or replace function public.clinica_version() returns integer language sql stable as $$select 31$$;
notify pgrst,'reload schema';
commit;
